#!/usr/bin/env bash
# Initialize a fresh local BECBarrier development environment.
# Generates local-only secrets into .env (gitignored) — no real values are
# ever committed. Requires a reachable PostgreSQL (see OPERATIONS.md).
set -euo pipefail

cd "$(dirname "$0")/.."

if [ -f .env ]; then
  echo ".env already exists — leaving it untouched (delete it to regenerate)."
  exit 0
fi

gen_hex() { openssl rand -hex 32; }
gen_token() { openssl rand -hex 24; }

cat > .env <<EOF
# Generated by scripts/setup-demo.sh — LOCAL DEVELOPMENT ONLY. Never commit.
APP_ENV=development
PORT=4000

# Adjust to your local PostgreSQL. The migration URL must be DDL-capable.
DATABASE_URL=postgresql://bb_api:bb_api_dev_password@localhost:5432/becbarrier_dev
MIGRATION_DATABASE_URL=postgresql://postgres:postgres@localhost:5432/becbarrier_dev
WORKER_DATABASE_URL=postgresql://bb_worker:bb_worker_dev_password@localhost:5432/becbarrier_dev
AUDIT_DATABASE_URL=postgresql://bb_audit_ro:bb_audit_ro_dev_password@localhost:5432/becbarrier_dev
DB_API_PASSWORD=bb_api_dev_password
DB_WORKER_PASSWORD=bb_worker_dev_password
DB_AUDIT_PASSWORD=bb_audit_ro_dev_password

SESSION_SIGNING_KEY=$(gen_hex)
PAYMENT_ENCRYPTION_KEY=$(gen_hex)
AUDIT_HMAC_KEY=$(gen_hex)
INTERNAL_SERVICE_TOKEN=$(gen_token)
ERP_ACK_SECRET=$(gen_token)

OIDC_ISSUER_URL=
OIDC_CLIENT_ID=

EMAIL_INTELLIGENCE_URL=http://localhost:8001
UPLOAD_MAX_BYTES=2097152
EMAIL_RULESET_VERSION=bec-rules-v1
CALLBACK_EXPIRY_HOURS=72

REDIS_URL=

WEB_ORIGIN=http://localhost:3000
NEXT_PUBLIC_API_BASE_URL=http://localhost:4000
NEXT_PUBLIC_WS_URL=ws://localhost:4000
EOF
chmod 600 .env
echo "Generated local .env with fresh development secrets."
echo "Next: npm run db:migrate && npm run db:setup-roles && npm run db:seed:synthetic"
